import { useParams } from "react-router-dom";
import projects from "../data/projects";
import Footer from "../components/footer/Footer";

const ProjectPage = () => {

    const { slug } = useParams();

    const project = projects.find(
        (item) => item.slug === slug
    );

    if (!project) {
        return <h1>Project Not Found</h1>;
    }

    return (
        <>
            <section className="Project_Page">
                <div className="Project_Page_Top">
                    <h3 className="text-body-lg">{project.title}</h3>
                    <p className="text-body-lg">{project.type}</p>
                    <img src={project.image} alt={project.title}/>
                </div>
                <div className="Project_Page_Bottom">
                    <p className="text-body">{project.detail}</p>
                    if ( {project.link_to} === null ) {
                        <p className="text-body-lg">{project.link_to.type}</p>
                    } else {
                        <a className="text-body-lg" href={project.link_to.url}>{project.link_to.type}</a>
                    }
                </div>
            </section>
            <Footer/>
        </>
    );
};

export default ProjectPage;
